const obstacles=buildWorld();
function perspective(fovy,aspect,near,far){let f=1/Math.tan(fovy/2),nf=1/(near-far);return new Float32Array([f/aspect,0,0,0,0,f,0,0,0,0,(far+near)*nf,-1,0,0,2*far*near*nf,0])}
function lookAt(eye,target,up){let z=norm(sub(eye,target)),x=norm({x:up.y*z.z-up.z*z.y,y:up.z*z.x-up.x*z.z,z:up.x*z.y-up.y*z.x}),y={x:z.y*x.z-z.z*x.y,y:z.z*x.x-z.x*x.z,z:z.x*x.y-z.y*x.x};return new Float32Array([x.x,y.x,z.x,0,x.y,y.y,z.y,0,x.z,y.z,z.z,0,-dot(x,eye),-dot(y,eye),-dot(z,eye),1])}
function matmul(a,b){let o=new Float32Array(16);for(let c=0;c<4;c++)for(let r=0;r<4;r++)o[c*4+r]=a[r]*b[c*4]+a[4+r]*b[c*4+1]+a[8+r]*b[c*4+2]+a[12+r]*b[c*4+3];return o}
let W=innerWidth,H=innerHeight;function resize(){W=innerWidth;H=innerHeight;let d=Math.min(devicePixelRatio||1,1.7);canvas.width=Math.floor(W*d);canvas.height=Math.floor(H*d);gl.viewport(0,0,canvas.width,canvas.height)}addEventListener('resize',resize);resize();gl.enable(gl.DEPTH_TEST);gl.enable(gl.CULL_FACE);gl.cullFace(gl.BACK);gl.clearColor(.025,.055,.06,1);
const player={pos:V(0,1.65,15),yaw:Math.PI,pitch:0,velY:0,health:100,armor:50,ammo:30,reserve:90,kills:0,alive:true};
let bots=[],shots=[],pickups=[],started=false,paused=false,over=false,last=performance.now(),fireCooldown=0,respawnTimer=0,reloadTimer=0,hitUntil=0,damageUntil=0,bob=0,moveKeys={},mouseDown=false,touchFire=false,stick={x:0,y:0},messageUntil=0,roundTime=0;
const botColors=[[.83,.19,.27],[.91,.37,.11],[.43,.25,.68],[.14,.65,.63],[.78,.65,.2],[.4,.61,.8]];
function makeBot(i){let pts=[V(-14,0,-13),V(14,0,-13),V(-14,0,13),V(14,0,13),V(-12,0,2),V(12,0,-2),V(1,0,-14),V(-1,0,14)];let p=pts[i%pts.length];return{id:Math.random().toString(36).slice(2,7),pos:V(p.x+(Math.random()-.5)*2,0,p.z+(Math.random()-.5)*2),hp:100,max:100,color:botColors[i%botColors.length],cooldown:Math.random()*1.7,dead:false,respawn:0,phase:Math.random()*8}}
function resetGame(){player.pos=V(0,1.65,15);player.yaw=Math.PI;player.pitch=0;player.velY=0;player.health=100;player.armor=50;player.ammo=30;player.reserve=90;player.kills=0;player.alive=true;bots=Array.from({length:6},(_,i)=>makeBot(i));shots=[];pickups=[{x:-10,z:-10,type:'health',active:true,t:0},{x:10,z:10,type:'armor',active:true,t:0},{x:0,z:-2,type:'ammo',active:true,t:0}];fireCooldown=0;respawnTimer=0;reloadTimer=0;roundTime=0;over=false;paused=false;started=true;$('#menu').classList.add('hidden');$('#pause').classList.add('hidden');$('#end').classList.add('hidden');$('#hud').style.display='block';$('#message').textContent='';syncHud();if(!matchMedia('(pointer:coarse)').matches)canvas.requestPointerLock?.()}
$('#start').onclick=resetGame;$('#again').onclick=resetGame;$('#resume').onclick=()=>{paused=false;$('#pause').classList.add('hidden');if(!matchMedia('(pointer:coarse)').matches)canvas.requestPointerLock?.()};$('#quit').onclick=()=>{paused=true;over=false;started=false;$('#pause').classList.add('hidden');$('#hud').style.display='none';$('#menu').classList.remove('hidden');document.exitPointerLock?.()};
function pauseGame(){if(!started||over||paused)return;paused=true;$('#pause').classList.remove('hidden')}
document.addEventListener('pointerlockchange',()=>{if(started&&!paused&&!document.pointerLockElement&&!matchMedia('(pointer:coarse)').matches)pauseGame()});
addEventListener('keydown',e=>{moveKeys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&started&&!paused)pauseGame();if(e.code==='KeyR'&&started&&!paused)reload();if(e.code==='Space'&&started&&!paused&&player.pos.y<=1.67)player.velY=7.1});addEventListener('keyup',e=>moveKeys[e.code]=false);
canvas.addEventListener('mousedown',e=>{if(e.button===0){mouseDown=true;if(started&&!paused&&!document.pointerLockElement&&!matchMedia('(pointer:coarse)').matches)canvas.requestPointerLock?.()}});addEventListener('mouseup',()=>mouseDown=false);
document.addEventListener('mousemove',e=>{if(document.pointerLockElement&&started&&!paused){player.yaw-=e.movementX*.0022;player.pitch=Math.max(-1.25,Math.min(1.25,player.pitch-e.movementY*.002))}});
function reload(){if(reloadTimer>0||player.ammo>=30||player.reserve<=0)return;reloadTimer=1.05;$('#message').textContent='RELOADING';messageUntil=performance.now()+1050}
function fire(){if(fireCooldown>0||reloadTimer>0||!player.alive)return;if(player.ammo<=0){reload();return}player.ammo--;fireCooldown=.18;syncHud();let dir=lookDir();let target=null,best=22;for(let b of bots){if(b.dead)continue;let center=V(b.pos.x,1.18,b.pos.z),d=sub(center,V(player.pos.x,player.pos.y,player.pos.z)),along=dot(d,dir),miss=len(sub(d,mul(dir,along)));if(along>0&&along<best&&miss<.7){best=along;target=b}}if(target){target.hp-=40;hitUntil=performance.now()+140;$('#crosshair').classList.add('hit');if(target.hp<=0){target.dead=true;target.respawn=2.8;player.kills++;feed('YOU',target.id);if(player.kills>=8)finish(true)}}else{shots.push({pos:add(V(player.pos.x,player.pos.y-.05,player.pos.z),mul(dir,.7)),vel:mul(dir,31),life:.55,color:C.lime,from:'player'})}if(player.ammo===0&&player.reserve)reload()}
function lookDir(){let cp=Math.cos(player.pitch);return norm(V(Math.sin(player.yaw)*cp,Math.sin(player.pitch),Math.cos(player.yaw)*cp))}
function feed(a,b){let el=document.createElement('div');el.className='feeditem';el.innerHTML=`<b>${a}</b> &nbsp;▸&nbsp; ${b}`;$('#killfeed').prepend(el);setTimeout(()=>el.remove(),2800)}
function finish(win){over=true;paused=true;$('#endtitle').textContent=win?'Arena champion.':'Shut down.';$('#endsub').textContent=win?'YOU DOMINATED THE PIT. CLEAN WORK.':`YOU SCORED ${player.kills} FRAGS. THE PIT CLAIMED YOU.`;$('#end').classList.remove('hidden');document.exitPointerLock?.()}
function syncHud(){$('#healthnum').textContent=Math.max(0,Math.ceil(player.health));$('#healthfill').style.width=Math.max(0,player.health)+'%';$('#armornum').textContent=Math.ceil(player.armor);$('#killnum').textContent=String(player.kills).padStart(2,'0');$('#scoreboard').innerHTML=`${String(player.kills).padStart(2,'0')} <span style="color:#576960">/ 08</span>`;$('#ammoval').textContent=player.ammo;$('#reserveval').textContent=player.reserve}
function collide(x,z,r=.48){if(Math.abs(x)>17.25||Math.abs(z)>17.25)return true;for(const o of obstacles)if(Math.abs(x-o.x)<o.r+r*.45&&Math.abs(z-o.z)<o.r+r*.45)return true;return false}
function move(dt){let f=V(Math.sin(player.yaw),0,Math.cos(player.yaw)),right=V(Math.cos(player.yaw),0,-Math.sin(player.yaw));let forward=(moveKeys.KeyW||moveKeys.ArrowUp?1:0)-(moveKeys.KeyS||moveKeys.ArrowDown?1:0)-stick.y;let side=(moveKeys.KeyD||moveKeys.ArrowRight?1:0)-(moveKeys.KeyA||moveKeys.ArrowLeft?1:0)+stick.x;let v=add(mul(f,forward),mul(right,side));if(len(v)>1)v=norm(v);let speed=(moveKeys.ShiftLeft||moveKeys.ShiftRight?8.3:5.7);let nx=player.pos.x+v.x*speed*dt,nz=player.pos.z+v.z*speed*dt;if(!collide(nx,player.pos.z))player.pos.x=nx;if(!collide(player.pos.x,nz))player.pos.z=nz;bob+=(len(v)>.1?dt*speed:dt)*.8;if(player.pos.y>1.65||player.velY>0){player.velY-=18*dt;player.pos.y+=player.velY*dt;if(player.pos.y<1.65){player.pos.y=1.65;player.velY=0}}if(moveKeys.Space&&player.pos.y<=1.66)player.velY=7.1;}
function updateBots(dt){for(let b of bots){if(b.dead){b.respawn-=dt;if(b.respawn<=0){let nb=makeBot(Math.floor(Math.random()*8));Object.assign(b,nb)}continue}b.phase+=dt*4;b.cooldown-=dt;let to=sub(V(player.pos.x,0,player.pos.z),b.pos),d=len(to),dir=norm(to);if(d>4){let speed=d>12?2.45:1.55,nx=b.pos.x+dir.x*speed*dt,nz=b.pos.z+dir.z*speed*dt;if(!collide(nx,b.pos.z,.45))b.pos.x=nx;if(!collide(b.pos.x,nz,.45))b.pos.z=nz}if(d<15&&b.cooldown<=0){b.cooldown=1.35+Math.random()*.6;let aim=norm(sub(V(player.pos.x,player.pos.y-.15,player.pos.z),V(b.pos.x,1.2,b.pos.z)));shots.push({pos:V(b.pos.x,1.25,b.pos.z),vel:mul(aim,10.5),life:2.1,color:C.red,from:'bot'})}}}
function updateShots(dt){for(let s of shots){s.pos=add(s.pos,mul(s.vel,dt));s.life-=dt;if(s.from==='bot'&&dist(s.pos,V(player.pos.x,player.pos.y-.15,player.pos.z))<.62&&player.alive){s.life=0;let hit=12;if(player.armor>0){let a=Math.min(player.armor,hit*.55);player.armor-=a;hit-=a}player.health-=hit;damageUntil=performance.now()+180;$('#damageflash').classList.add('on');if(player.health<=0){player.health=0;player.alive=false;respawnTimer=2.4;feed('YOU','DOWN')}syncHud()}else if(s.from==='player'&&s.pos.y<0)s.life=0}shots=shots.filter(s=>s.life>0);if(!player.alive){respawnTimer-=dt;if(respawnTimer<=0){player.alive=true;player.health=100;player.armor=35;player.pos=V((Math.random()-.5)*5,1.65,14);player.yaw=Math.PI;syncHud()}}}
function updatePickups(dt){for(let p of pickups){p.t+=dt;if(!p.active)continue;if(Math.hypot(player.pos.x-p.x,player.pos.z-p.z)<1.15){if(p.type==='health'&&player.health<100)player.health=Math.min(100,player.health+35);else if(p.type==='armor'&&player.armor<100)player.armor=Math.min(100,player.armor+35);else if(p.type==='ammo'&&player.reserve<150)player.reserve=Math.min(150,player.reserve+45);else continue;p.active=false;p.cooldown=9;syncHud();$('#message').textContent=p.type==='health'?'VITALS +35':p.type==='armor'?'ARMOR +35':'AMMO +45';messageUntil=performance.now()+1300}if(!p.active){p.cooldown-=dt;if(p.cooldown<=0)p.active=true}}}

